import{_ as t,o as i,c as s,a3 as a}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"C++ Runtimes from Source","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"C++ Runtimes from Source | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/features/runtimes-from-source"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/features/runtimes-from-source"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/features/runtimes-from-source"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/features/runtimes-from-source"}]]},"headers":[],"relativePath":"xclang/features/runtimes-from-source.md","filePath":"en/xclang/features/runtimes-from-source.md","lastUpdated":1791579933000}'),o={name:"xclang/features/runtimes-from-source.md"};function n(r,e,d,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="c-runtimes-from-source" tabindex="-1">C++ Runtimes from Source <a class="header-anchor" href="#c-runtimes-from-source" aria-label="Permalink to &quot;C++ Runtimes from Source&quot;">​</a></h1><p>xclang&#39;s prebuilt C++ runtimes are one build of libc++, libc++abi and libunwind per target: no hardening mode, ABI version 1, exceptions and RTTI, no instrumentation but the ASan libc++ (<a href="./sanitizers">sanitizers</a>). A CMake or Bazel build can instead compile them from the sources every toolchain carries, with options of its own, and link its programs against those. This is for what the prebuilt runtimes cannot be:</p><ul><li><strong>MemorySanitizer</strong>, which needs every library instrumented, libc++ too, and compiler-rt&#39;s runtime of it, which the toolchain does not carry. ThreadSanitizer and AddressSanitizer report through an instrumented libc++ too.</li><li><strong>libc++&#39;s hardening modes</strong>, checked inside the library as well as in its headers.</li><li><strong>ABI options</strong>: libc++&#39;s ABI version 2, bounded iterators, an inline namespace of one&#39;s own.</li><li><strong>No exceptions, no RTTI</strong> in libc++ and libc++abi.</li><li><strong>LTO of libc++ with the program</strong> (CMake).</li></ul><p>The prebuilt runtimes stay the default. Runtimes from source are in no release yet (<a href="./../design/roadmap#libc-on-demand">Unreleased</a>); the toolchains of the release after 23.1.2.10 carry the sources.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="cmake" tabindex="-1">CMake <a class="header-anchor" href="#cmake" aria-label="Permalink to &quot;CMake&quot;">​</a></h3><p>The option is the toolchain file&#39;s, <code>XCLANG_RUNTIMES=source</code>, with libc++&#39;s options next to it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$XCLANG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/lib/cmake/xclang/toolchain.cmake&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -DXCLANG_RUNTIMES=source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DXCLANG_LIBCXX_HARDENING=fast</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The first configure builds the variant, about half a minute on four cores, into <code>build/xclang-runtimes/&lt;target&gt;-&lt;digest&gt;</code>; later configures use it, and other options make another variant beside it. Every compile and link of the build is against it, CMake&#39;s own checks too, and <code>xclang::std</code> is built from its modules. A MemorySanitizer build, which builds compiler-rt&#39;s runtime of it first:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-msan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$XCLANG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/lib/cmake/xclang/toolchain.cmake&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -DXCLANG_RUNTIMES=source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DXCLANG_SANITIZER=memory</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_BUILD_TYPE=RelWithDebInfo</span></span></code></pre></div><p><code>XCLANG_SANITIZER</code> gives the whole build its <code>-fsanitize=</code> and runtimes that suit it, so the project&#39;s flags need no <code>-fsanitize=</code> of their own. With the prebuilt runtimes it works too, for the sanitizers they have: <code>address</code> then links the prebuilt ASan libc++.</p><p>For another target, add <code>-DXCLANG_TARGET=&lt;target&gt;</code>: the variant is built for it, by the same toolchain file.</p><h3 id="bazel" tabindex="-1">Bazel <a class="header-anchor" href="#bazel" aria-label="Permalink to &quot;Bazel&quot;">​</a></h3><p>The flags of the whole build are in <code>@xclang//runtimes</code>, and the sanitizers are the features they always were:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --@xclang//runtimes:source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --@xclang//runtimes:hardening=fast</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --@xclang//runtimes:source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features=msan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //...</span></span></code></pre></div><p>The runtimes are libraries of the toolchain&#39;s repository, compiled for the target platform with the build&#39;s features (a sanitizer&#39;s instrumentation) and <code>--copt</code>, and cached as any other action. A <code>.bazelrc</code> names the variants a project uses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build:msan --@xclang//runtimes:source --features=msan</span></span>
<span class="line"><span>build:hardened --@xclang//runtimes:source --@xclang//runtimes:hardening=extensive</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>CMake (toolchain file)</th><th>Bazel</th></tr></thead><tbody><tr><td>runtimes from source</td><td><code>XCLANG_RUNTIMES=source</code></td><td><code>--@xclang//runtimes:source</code></td></tr><tr><td>libc++&#39;s hardening mode: <code>none</code>, <code>fast</code>, <code>extensive</code>, <code>debug</code></td><td><code>XCLANG_LIBCXX_HARDENING</code></td><td><code>--@xclang//runtimes:hardening</code></td></tr><tr><td>libc++&#39;s ABI version, <code>1</code> or <code>2</code></td><td><code>XCLANG_LIBCXX_ABI_VERSION</code></td><td><code>--@xclang//runtimes:abi_version</code></td></tr><tr><td>libc++&#39;s inline namespace, <code>__&lt;name&gt;</code></td><td><code>XCLANG_LIBCXX_ABI_NAMESPACE</code></td><td><code>--@xclang//runtimes:abi_namespace</code></td></tr><tr><td>libc++&#39;s ABI macros, <code>_LIBCPP_ABI_*</code></td><td><code>XCLANG_LIBCXX_ABI_DEFINES</code> (a list)</td><td><code>--@xclang//runtimes:abi_defines</code> (comma-separated)</td></tr><tr><td>libc++ and libc++abi without exceptions</td><td><code>XCLANG_RUNTIMES_EXCEPTIONS=OFF</code></td><td><code>--@xclang//runtimes:exceptions=false</code></td></tr><tr><td>libc++ without RTTI (and without exceptions)</td><td><code>XCLANG_RUNTIMES_RTTI=OFF</code></td><td><code>--@xclang//runtimes:rtti=false</code></td></tr><tr><td>sanitizers: <code>address</code>, <code>memory</code>, <code>thread</code>, <code>undefined</code>, <code>leak</code></td><td><code>XCLANG_SANITIZER</code></td><td><code>--features=asan</code>, <code>msan</code>, <code>tsan</code>, <code>ubsan</code>, <code>lsan</code></td></tr><tr><td>more compile options of libc++ and libc++abi</td><td><code>XCLANG_RUNTIMES_FLAGS</code></td><td>the build&#39;s <code>--copt</code></td></tr><tr><td>LTO of libc++ with the program</td><td><code>XCLANG_RUNTIMES_FLAGS=-flto=thin</code></td><td>not available</td></tr><tr><td>more options of LLVM&#39;s CMake build</td><td><code>XCLANG_RUNTIMES_CMAKE_ARGS</code></td><td></td></tr><tr><td>where the variants are built</td><td><code>XCLANG_RUNTIMES_DIR</code></td><td>Bazel&#39;s output base and caches</td></tr></tbody></table><p>The program&#39;s own options are its own: a build without exceptions passes <code>-fno-exceptions</code> (<code>CMAKE_CXX_FLAGS</code>, <code>--copt</code>) as well. The <a href="./../reference/cmake-api#runtimes-from-source">CMake API</a> and the <a href="./../reference/bazel-api#runtimes-from-source">Bazel API</a> list them again.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>The same build as the prebuilt runtimes.</strong> CMake builds LLVM&#39;s <code>runtimes/</code> with the CMake cache and options of xclang&#39;s own build of the runtimes, by the toolchain file and the config file of the target. With no options, the result is the prebuilt runtimes: the same <code>__config_site</code>, and the same code. Bazel compiles the same translation units with the same flags, which <code>packages/bazel/runtimes.ts</code> takes from LLVM&#39;s CMake build of every target.</li><li><strong>What is built</strong>: libc++ with libc++abi in it, libc++experimental, and libunwind (none for macOS, which unwinds with the system&#39;s). With MemorySanitizer, compiler-rt&#39;s runtime of it.</li><li><strong>In place of the prebuilt ones.</strong> The variant&#39;s <code>__config_site</code> comes before libc++&#39;s other headers, and its libraries are linked instead of the prebuilt ones (<code>-nostdlib++</code>). <code>import std</code> follows the variant: <code>xclang::std</code> and <code>@xclang//bazel:std</code> are built from it.</li><li><strong>libunwind stays uninstrumented</strong> with sanitizers, as in the prebuilt ASan libc++: the sanitizers&#39; runtimes unwind with it, and MemorySanitizer would report the registers it reads.</li><li><strong>MemorySanitizer is for the Linux targets</strong> (glibc), x64 and arm64. Its runtime is linked into executables as clang links the others, whole, with its interface exported.</li><li><strong>Every library of a program must use the same variant.</strong> A library built against the prebuilt runtimes, with another ABI namespace, ABI version or set of ABI macros, does not link, or breaks at run time; under MemorySanitizer, its code reports what it was not instrumented to see.</li><li><strong>Bazel does not run ThinLTO on the runtimes</strong>: <code>--features=thin_lto</code> links programs of ThinLTO against runtimes of native code. Bazel&#39;s ThinLTO backends compile the objects of the libraries it knows, and the toolchain links the runtimes&#39; by their paths.</li><li><strong>CMake needs Python 3</strong>, as LLVM&#39;s build of the runtimes does. Bazel needs nothing more.</li></ul><h2 id="the-sources" tabindex="-1">The Sources <a class="header-anchor" href="#the-sources" aria-label="Permalink to &quot;The Sources&quot;">​</a></h2><p>Every toolchain directory has the sources once, for every target, in <code>libc++/src</code>, next to libc++&#39;s headers: llvm-project&#39;s own layout (<code>runtimes/</code>, <code>cmake/</code>, <code>llvm/cmake/</code>, <code>libcxx/</code>, <code>libcxxabi/</code>, <code>libunwind/</code>, <code>compiler-rt/</code>, and the headers of LLVM&#39;s libc that libc++ includes), without tests and documentation, with xclang&#39;s <a href="./../reference/patches">patches</a> of libc++ applied. They are 35 MB unpacked, 2.3 MB of each archive.</p><h2 id="not-yet-supported" tabindex="-1">Not Yet Supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not Yet Supported&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>status</th></tr></thead><tbody><tr><td><a href="./../design/roadmap#runtimes-msvc">Runtimes from source for the MSVC targets</a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./../design/roadmap#runtimes-bazel-lto">LTO of the runtimes with the program in Bazel</a></td><td><span class="status-badge note">Considered</span></td></tr></tbody></table>`,26)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
